import mongoose from"mongoose";const reviewSchema=new mongoose.Schema({productId:{type:mongoose.Schema.Types.ObjectId,ref:"product",required:!0},name:{type:String,required:!0,trim:!0},email:{type:String,required:!0,trim:!0},rating:{type:Number,required:!0,min:1,max:5},comment:{type:String,required:!0,trim:!0},approved:{type:Boolean,default:!1}},{timestamps:!0}),reviewModel=mongoose.models.review||mongoose.model("review",reviewSchema);export default reviewModel;